-- Order journey and private artwork originals. Apply after 004_sales.sql.
begin;

alter table emblara.orders add column source text not null default 'website' check (source in ('website','quote'));
alter table emblara.orders add column stage text not null default 'new' check (stage in ('new','awaiting_payment','paid','in_production','shipped','delivered','closed','cancelled'));
alter table emblara.orders add column artwork_status text not null default 'not_received' check (artwork_status in ('not_received','received','approved','needs_changes'));
alter table emblara.orders add column artwork_note text check(char_length(artwork_note)<=2000);
alter table emblara.orders add column quote_id uuid references quoting.quotes(id);
alter table emblara.orders add column invoice_id uuid references invoicing.invoices(id);
alter table emblara.order_items alter column product_slug drop not null;
alter table emblara.order_items add column catalogue_item_id uuid references invoicing.catalogue_items(id);
create unique index orders_live_quote_once on emblara.orders(quote_id) where quote_id is not null and stage <> 'cancelled';
create unique index orders_live_invoice_once on emblara.orders(invoice_id) where invoice_id is not null and stage <> 'cancelled';

create table emblara.order_artwork (
 id uuid primary key default gen_random_uuid(), order_id uuid references emblara.orders(id), kind text not null check(kind in ('original','processed')), storage_key text not null unique check(storage_key ~ '^artwork/[0-9a-f-]{36}/[a-z0-9]+$'), file_name text not null check(char_length(file_name) between 1 and 200), size_bytes bigint not null check(size_bytes between 1 and 26214400), content_type text not null check(content_type in ('image/png','image/jpeg','image/webp','image/svg+xml','application/pdf')), sha256 bytea not null check(octet_length(sha256)=32), created_by uuid references emblara.staff(id), created_at timestamptz not null default now(), status_note text check(char_length(status_note)<=1000)
);
create index order_artwork_order_idx on emblara.order_artwork(order_id,created_at);

create function emblara.orders_stage_on_payment() returns trigger language plpgsql set search_path='' as $$ begin if new.payment_status='paid' and old.payment_status is distinct from 'paid' and new.stage in ('new','awaiting_payment') then new.stage='paid'; end if; return new; end $$;
create trigger orders_stage_on_payment before update on emblara.orders for each row execute function emblara.orders_stage_on_payment();

-- The checkout flow can reserve one UUID-bound object key. No customer can select an
-- arbitrary key or attach an object to a different order.
create function emblara.create_artwork_upload(p_name text,p_size bigint,p_type text,p_sha_hex text) returns table(id uuid,storage_key text) language plpgsql security definer set search_path='' as $$ declare v_id uuid:=gen_random_uuid(); begin if emblara.flow()<>'checkout' or p_name is null or char_length(btrim(p_name)) not between 1 and 200 or p_size not between 1 and 26214400 or p_type not in ('image/png','image/jpeg','image/webp','image/svg+xml','application/pdf') or p_sha_hex !~ '^[0-9a-f]{64}$' then raise exception 'artwork_upload_invalid' using errcode='22023'; end if; insert into emblara.order_artwork(id,kind,storage_key,file_name,size_bytes,content_type,sha256) values(v_id,'original','artwork/'||v_id::text||'/original',btrim(p_name),p_size,p_type,decode(p_sha_hex,'hex')); return query select v_id,'artwork/'||v_id::text||'/original'; end $$;
create function emblara.attach_artwork_to_order(p_order uuid,p_artwork uuid) returns void language plpgsql security definer set search_path='' as $$ begin if emblara.flow()<>'checkout' then raise exception 'not_checkout' using errcode='42501'; end if; if not exists(select 1 from emblara.orders where id=p_order) then raise exception 'order_not_found'; end if; update emblara.order_artwork set order_id=p_order where id=p_artwork and order_id is null and kind='original'; if not found then raise exception 'artwork_not_available'; end if; update emblara.orders set artwork='attached', artwork_status='received' where id=p_order; end $$;
create function emblara.get_pending_artwork(p_artwork uuid) returns table(id uuid,storage_key text,size_bytes bigint,content_type text,sha256 bytea) language sql security definer set search_path='' as $$ select a.id,a.storage_key,a.size_bytes,a.content_type,a.sha256 from emblara.order_artwork a where emblara.flow()='checkout' and a.id=p_artwork and a.order_id is null and a.kind='original' $$;

create function emblara.set_artwork_status(p_order uuid,p_status text,p_note text default null) returns emblara.orders language plpgsql security definer set search_path='' as $$ declare v emblara.orders; begin if not emblara.is_staff() or p_status not in ('not_received','received','approved','needs_changes') or (p_status='needs_changes' and nullif(btrim(p_note),'') is null) then raise exception 'artwork_status_invalid' using errcode='22023'; end if; update emblara.orders set artwork_status=p_status,artwork_note=nullif(btrim(p_note),'') where id=p_order returning * into v; if not found then raise exception 'order_not_found'; end if; return v; end $$;
create function emblara.advance_order(p_order uuid,p_to text,p_reason text default null) returns emblara.orders language plpgsql security definer set search_path='' as $$ declare v emblara.orders; begin if not emblara.is_staff() then raise exception 'not_staff' using errcode='42501'; end if; select * into v from emblara.orders where id=p_order for update; if not found then raise exception 'order_not_found'; end if; if v.stage='new' and p_to='awaiting_payment' then if not exists(select 1 from invoicing.invoices where id=v.invoice_id and status='sent') then raise exception 'sent_invoice_required'; end if; elsif v.stage='in_production' and p_to='shipped' then null; elsif v.stage='shipped' and p_to='delivered' then null; elsif v.stage='delivered' and p_to='closed' then null; elsif v.stage in ('new','awaiting_payment','paid') and p_to='cancelled' and nullif(btrim(p_reason),'') is not null then null; else raise exception 'stage_move_not_allowed: new->awaiting_payment; in_production->shipped; shipped->delivered; delivered->closed; or cancellation with a reason'; end if; update emblara.orders set stage=p_to,artwork_note=case when p_to='cancelled' then btrim(p_reason) else artwork_note end,fulfillment_status=case when p_to='in_production' then 'processing' when p_to in ('shipped','delivered','closed') and payment_status='paid' then 'fulfilled' else fulfillment_status end where id=p_order returning * into v; return v; end $$;
create function emblara.create_order_from_quote(p_quote uuid) returns uuid language plpgsql security definer set search_path='' as $$ declare q quoting.quotes; v_id uuid; begin if not emblara.is_staff() then raise exception 'not_staff' using errcode='42501'; end if; select * into q from quoting.quotes where id=p_quote for update; if not found or q.status<>'accepted' then raise exception 'quote_not_accepted'; end if; if exists(select 1 from emblara.orders where quote_id=p_quote and stage<>'cancelled') then raise exception 'quote_order_exists'; end if; insert into emblara.orders(number,currency,amount_total_pence,payment_status,fulfillment_status,artwork,source,stage,quote_id) values('EM-'||upper(substr(encode(gen_random_bytes(6),'hex'),1,6)),'gbp',q.total_pence,'pending','unfulfilled','later','quote','new',p_quote) returning id into v_id; insert into emblara.order_items(order_id,product_name,options,quantity,unit_amount_pence,line_amount_pence) select v_id,description,'{}'::jsonb,quantity,unit_price_pence,line_total_pence from quoting.quote_lines where quote_id=p_quote order by line_no; return v_id; end $$;
create function invoicing.create_invoice_from_order(p_order uuid,p_client uuid) returns uuid language plpgsql security definer set search_path='' as $$ declare v_order emblara.orders; v_invoice uuid; v_line record; begin if not emblara.is_staff() then raise exception 'not_staff' using errcode='42501'; end if; select * into v_order from emblara.orders where id=p_order for update; if not found or v_order.invoice_id is not null then raise exception 'order_invoice_invalid'; end if; v_invoice:=invoicing.create_invoice(p_client,null); for v_line in select * from emblara.order_items where order_id=p_order order by created_at loop perform invoicing.add_invoice_line(v_invoice,v_line.product_name||case when v_line.options::text='{}' then '' else ' — '||v_line.options::text end,v_line.quantity,v_line.unit_amount_pence); end loop; if (select total_pence from invoicing.invoices where id=v_invoice)<>v_order.amount_total_pence then raise exception 'invoice_total_mismatch'; end if; update emblara.orders set invoice_id=v_invoice where id=p_order; return v_invoice; end $$;
create function emblara.settle_order_from_invoice(p_order uuid) returns emblara.orders language plpgsql security definer set search_path='' as $$ declare v emblara.orders; begin if not emblara.is_staff() then raise exception 'not_staff' using errcode='42501'; end if; select * into v from emblara.orders where id=p_order for update; if not found or not exists(select 1 from invoicing.invoices where id=v.invoice_id and status='paid') then raise exception 'paid_invoice_required'; end if; update emblara.orders set payment_status='paid',paid_at=coalesce(paid_at,now()) where id=p_order returning * into v; return v; end $$;

alter table emblara.order_artwork enable row level security;
grant select on emblara.order_artwork to emblara_app;
create policy order_artwork_staff_read on emblara.order_artwork for select to emblara_app using(emblara.is_staff());
revoke update on emblara.orders from emblara_app;
grant update(payment_status,fulfillment_status,paid_at,stripe_session_id,stripe_payment_intent,email,customer_name,phone,shipping) on emblara.orders to emblara_app;
revoke all on function emblara.create_artwork_upload(text,bigint,text,text),emblara.attach_artwork_to_order(uuid,uuid),emblara.get_pending_artwork(uuid),emblara.set_artwork_status(uuid,text,text),emblara.advance_order(uuid,text,text),emblara.create_order_from_quote(uuid),invoicing.create_invoice_from_order(uuid,uuid),emblara.settle_order_from_invoice(uuid) from public;
grant execute on function emblara.create_artwork_upload(text,bigint,text,text),emblara.attach_artwork_to_order(uuid,uuid),emblara.get_pending_artwork(uuid),emblara.set_artwork_status(uuid,text,text),emblara.advance_order(uuid,text,text),emblara.create_order_from_quote(uuid),invoicing.create_invoice_from_order(uuid,uuid),emblara.settle_order_from_invoice(uuid) to emblara_app;
commit;
